/**
 * Local pHash index for camera scanning, generated by scripts/prepare-hashes.js
 * and served from public/card-hashes.bin (compact binary). The build appends one
 * length-prefixed record per face as it hashes — an append-only stream that can
 * be cancelled and resumed without losing work. Loaded once (idempotent) into
 * memory; the hash scanner matches photographed card artwork against it — a fast,
 * network-free identification channel that runs in parallel with OCR.
 *
 * File layout: a small header (magic "DCH1", version, HASH_ART_REGION, match
 * threshold), then one record per unique visual face (reprints sharing artwork
 * collapse to one entry at build time). Each record stores the Scryfall id plus,
 * for every aspect class, the stored variant hashes as packed u32 hi/lo word
 * pairs — no hex strings, so the served index is ~half the size it was as JSONL.
 * At load we build per-class SoA arrays (hi/lo/owner) so a frame scan is a tight
 * numeric Hamming loop. A missing file degrades gracefully: the scanner reports
 * "not ready" and OCR remains the only channel. Mirrors scripts/hash-index-bin.js.
 */

import { HASH_ART_REGION, HASH_MATCH_THRESHOLD } from '../ocr/phash';
import { parseHashIndex } from './builders';
import type { CardHashEntry, PackedClass, CardHashIndex } from './builders';
import { requestLoad, workersSupported } from './workerClient';

export type { CardHashEntry, PackedClass, CardHashIndex };

let index: CardHashIndex = {
  ready: false,
  entries: [],
  region: HASH_ART_REGION,
  threshold: HASH_MATCH_THRESHOLD,
  packed: {}
};
let loadPromise: Promise<CardHashIndex> | null = null;

/** Main-thread fallback when Web Workers are unavailable. */
function loadOnMainThread(): Promise<CardHashIndex> {
  return (async () => {
    try {
      const response = await fetch(`${import.meta.env.BASE_URL}card-hashes.bin`, {
        headers: { Accept: 'application/octet-stream' }
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      index = parseHashIndex(await response.arrayBuffer());
    } catch (err) {
      console.warn('Failed to load card hash index — OCR will be the only identification channel:', err);
      // index stays { ready: false } → hash channel skipped, OCR unaffected
    }
    return index;
  })();
}

/**
 * Loads the hash index (idempotent — concurrent calls share one fetch). The
 * fetch + parse run in a Web Worker so the ~12 MB index is walked and packed off
 * the main thread. Resolves even on failure with `ready: false` so the scanner
 * can simply skip the hash channel and rely on OCR.
 */
export function ensureCardHashes(): Promise<CardHashIndex> {
  if (!loadPromise) {
    loadPromise = (async () => {
      // Fast path: fetch + parse in a worker so the ~12 MB index is walked and
      // packed off the main thread. If the worker is unavailable or fails for any
      // reason, fall back to loading on the main thread rather than giving up.
      if (workersSupported()) {
        try {
          const payload = await requestLoad<CardHashIndex>('card-hashes');
          index = {
            ready: payload.ready,
            entries: payload.entries,
            region: payload.region,
            threshold: payload.threshold,
            packed: payload.packed
          };
          return index;
        } catch (err) {
          console.warn('Worker hash-index load failed — retrying on main thread:', err);
        }
      }
      return loadOnMainThread();
    })();
  }
  return loadPromise;
}

/** True once the index is loaded and usable for matching. */
export function isCardHashesReady(): boolean {
  return index.ready;
}